from protocols import signature

_CACHE = {}


def _signature(kind, payload):
    key = (kind, payload)
    try:
        return _CACHE[key]
    except KeyError:
        pass
    value = signature(kind, payload)
    if len(_CACHE) > 200000:
        _CACHE.clear()
    _CACHE[key] = value
    return value


